                String::from("api"),
                format!("{api_repo}/pulls/{pull}/comments"),
                String::from("--paginate"),
            ],
        );
        push_capture(
            &mut captures,
            "pull_reviews",
            &format!("pr-{pull}-reviews.json"),
            vec![
                String::from("gh"),
                String::from("api"),
                format!("{api_repo}/pulls/{pull}/reviews"),
