/// Solve an Anthropic Messages request and wrap the answer as an [`AnthropicMessage`].
///
/// When the shared agentic loop asks for tools (`finish_reason: "tool_calls"`), the
/// response carries `tool_use` content blocks and `stop_reason: "tool_use"`;
/// otherwise it carries a single `text` block and `stop_reason: "end_turn"`. When the
/// request enables extended thinking, a concrete `thinking` content block carrying the
/// solver's naturalized reasoning trace leads the response (issue #488).
#[must_use]
pub fn create_anthropic_message_with_solver(
    request: &AnthropicMessagesRequest,
    solver: &UniversalSolver,
) -> AnthropicMessage {
    let chat_request = request.to_chat_completion_request();
    let completion = create_chat_completion_with_solver(&chat_request, solver);
    anthropic_message_from_chat_completion(request, &completion)
}

#[must_use]
pub fn create_anthropic_message_with_solver_and_memory(
    request: &AnthropicMessagesRequest,
    solver: &UniversalSolver,
    memory_events: &[MemoryEvent],
) -> AnthropicMessage {
    let chat_request = request.to_chat_completion_request();
    let completion =
        create_chat_completion_with_solver_and_memory(&chat_request, solver, memory_events);
    anthropic_message_from_chat_completion(request, &completion)
}

fn anthropic_message_from_chat_completion(
    request: &AnthropicMessagesRequest,
    completion: &ChatCompletion,
) -> AnthropicMessage {
    let model = crate::seed::resolve_model_id(request.model.as_deref());
    let choice = completion.choices.first();
    let requests_tools = choice.is_some_and(|choice| choice.finish_reason == "tool_calls");

    let (mut content, stop_reason, seed) = if requests_tools {
        let calls = choice
            .map(|choice| choice.message.tool_calls.clone())
            .unwrap_or_default();
        let seed = calls
            .iter()
            .map(|call| format!("{}({})", call.function.name, call.function.arguments))
            .collect::<Vec<_>>()
            .join("|");
        let blocks = calls.into_iter().map(tool_call_to_block).collect();
        (blocks, String::from("tool_use"), seed)
    } else {
        let text = choice
            .map(|choice| choice.message.content.plain_text())
            .unwrap_or_default();
        (
            vec![AnthropicContentBlock::text(text.clone())],
            String::from("end_turn"),
            text,
        )
    };

    // Extended thinking: when the client enabled it, lead the response with a
    // concrete `thinking` block built from the solver's naturalized reasoning
    // trace, mirroring the real Anthropic API (issue #488).
    if request.wants_thinking() {
        let steps = choice
            .map(|choice| choice.message.thinking_steps.as_slice())
            .unwrap_or_default();
        if let Some(block) = anthropic_thinking_block(steps) {
            content.insert(0, block);
        }
    }

    AnthropicMessage {
        id: stable_id("msg", &seed),
        kind: String::from("message"),
        role: String::from("assistant"),
        model,
        content,
        stop_reason,
        stop_sequence: None,
        usage: AnthropicUsage {
            input_tokens: completion.usage.prompt_tokens,
            output_tokens: completion.usage.completion_tokens,
        },
        context: json!(ContextCapacity::current()
            .unwrap_or_else(|_| { ContextCapacity::from_bytes(0, 0, avg_utf8_bytes_per_char()) })),
    }
}

/// Build the extended-thinking `thinking` content block from the solver's
/// concrete reasoning trace (issue #488). Each step is rendered by its
/// naturalized, human-readable `summary`; composite children are indented with a
/// `↳` marker so the recursively composite structure survives into the Anthropic
/// surface. The deterministic `signature` is a stable hash of the trace.
fn anthropic_thinking_block(steps: &[ThinkingStep]) -> Option<AnthropicContentBlock> {
    let text = render_thinking_steps(steps);
    if text.is_empty() {
        return None;
    }
    let signature = stable_id("thinking_signature", &text);
    Some(AnthropicContentBlock::thinking(text, signature))
}

/// Translate one OpenAI `tool_calls` entry into an Anthropic `tool_use` block,
/// parsing the JSON arguments back into the structured `input` object.
fn tool_call_to_block(call: ToolCall) -> AnthropicContentBlock {
    let input = serde_json::from_str::<Value>(&call.function.arguments)
        .unwrap_or_else(|_| Value::Object(serde_json::Map::new()));
    AnthropicContentBlock::ToolUse {
        id: call.id,
        name: call.function.name,
        input,
    }
}

/// Render an [`AnthropicMessage`] as the Anthropic Server-Sent-Events stream.
///
/// `claude` consumes this when `stream: true`. The sequence mirrors the real
/// API: `message_start`, one `content_block_start` / `content_block_delta` /
/// `content_block_stop`, then `message_delta` and `message_stop`.
#[must_use]
pub fn anthropic_message_sse(message: &AnthropicMessage) -> String {
    let message_start = json!({
        "type": "message_start",
        "message": {
            "id": message.id,
            "type": "message",
            "role": "assistant",
            "model": message.model,
            "content": [],
            "stop_reason": Value::Null,
            "stop_sequence": Value::Null,
            "context": message.context,
            "usage": {

### anthropic stream
    });
    let message_stop = json!({"type": "message_stop"});

    let mut body = String::new();
    push_sse_event(&mut body, "message_start", &message_start);
    for (index, block) in message.content.iter().enumerate() {
        push_content_block_events(&mut body, index, block);
    }
    push_sse_event(&mut body, "message_delta", &message_delta);
    push_sse_event(&mut body, "message_stop", &message_stop);
    body
}

/// Emit the `content_block_start` / `content_block_delta` / `content_block_stop`
/// trio for one content block. A `text` block streams a `text_delta`; a `tool_use`
/// block streams its `input` as a single `input_json_delta` (the Anthropic shape an
/// agentic CLI expects when assembling a tool call); a `thinking` block streams a
/// `thinking_delta` followed by a `signature_delta` (issue #488).
fn push_content_block_events(body: &mut String, index: usize, block: &AnthropicContentBlock) {
    match block {
        AnthropicContentBlock::Thinking {
            thinking,
            signature,
        } => {
            push_sse_event(
                body,
                "content_block_start",
                &json!({
                    "type": "content_block_start",
                    "index": index,
                    "content_block": {"type": "thinking", "thinking": ""}
                }),
            );
            push_sse_event(
                body,
                "content_block_delta",
                &json!({
                    "type": "content_block_delta",
                    "index": index,
                    "delta": {"type": "thinking_delta", "thinking": thinking}
                }),
            );
            push_sse_event(
                body,
                "content_block_delta",
                &json!({
                    "type": "content_block_delta",
                    "index": index,
                    "delta": {"type": "signature_delta", "signature": signature}
                }),
            );
        }
        AnthropicContentBlock::Text { text } => {
            push_sse_event(
                body,
                "content_block_start",
                &json!({
                    "type": "content_block_start",
                    "index": index,
                    "content_block": {"type": "text", "text": ""}
                }),
            );
            push_sse_event(
                body,
                "content_block_delta",
                &json!({
                    "type": "content_block_delta",
                    "index": index,
                    "delta": {"type": "text_delta", "text": text}
                }),
            );
        }
        AnthropicContentBlock::ToolUse { id, name, input } => {
            push_sse_event(
                body,
                "content_block_start",
                &json!({
                    "type": "content_block_start",
                    "index": index,
                    "content_block": {"type": "tool_use", "id": id, "name": name, "input": {}}
                }),
            );
            push_sse_event(
                body,
                "content_block_delta",
                &json!({
                    "type": "content_block_delta",
                    "index": index,
                    "delta": {"type": "input_json_delta", "partial_json": input.to_string()}
                }),
            );
        }
    }
    push_sse_event(
        body,
        "content_block_stop",
        &json!({"type": "content_block_stop", "index": index}),
    );
}

fn push_sse_event(body: &mut String, event: &str, data: &Value) {
    body.push_str("event: ");
    body.push_str(event);
    body.push('\n');
    body.push_str("data: ");
    body.push_str(&data.to_string());
    body.push_str("\n\n");
}

/// Flatten Anthropic content (a bare string, an array of content blocks, or a
/// single block object) into plain text. Non-text blocks (images, `tool_use`) are
/// skipped — the symbolic solver works on text.
fn anthropic_content_to_text(value: &Value) -> String {
    match value {
        Value::String(text) => text.clone(),
        Value::Array(blocks) => blocks
            .iter()
            .map(anthropic_content_to_text)
            .filter(|text| !text.trim().is_empty())
            .collect::<Vec<_>>()
            .join("\n"),
        Value::Object(object) => object
            .get("text")
            .and_then(Value::as_str)
            .map(ToOwned::to_owned)
            .unwrap_or_default(),
        _ => String::new(),
    }
}

### gemini
//! Google Gemini / Vertex `generateContent` adapters over the shared solver.
//!
//! The adapter is intentionally thin: it translates Gemini-shaped content parts
//! into the same chat request used by the OpenAI and Anthropic envelopes, invokes
//! [`UniversalSolver`], then wraps the answer back into a
//! `GenerateContentResponse`-shaped object.

use std::collections::HashMap;

use serde::Deserialize;
use serde_json::{json, Value};

use crate::context_capacity::{avg_utf8_bytes_per_char, ContextCapacity};
use crate::memory::MemoryEvent;
use crate::protocol::{
    create_chat_completion_with_solver_and_memory, ChatCompletion, ChatCompletionRequest,
    ChatMessage, MessageContent, ToolCall,
};
use crate::seed::{canonical_model_id, resolve_model_id};
use crate::solver::UniversalSolver;

#[derive(Debug, Clone, PartialEq, Default, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct GeminiGenerateContentRequest {
    #[serde(default)]
    contents: Vec<GeminiContent>,
    #[serde(default)]
    system_instruction: Option<GeminiContent>,
    #[serde(default)]
    generation_config: Option<GeminiGenerationConfig>,
    #[serde(default)]
    tools: Vec<Value>,
}

#[derive(Debug, Clone, PartialEq, Default, Deserialize)]
struct GeminiGenerationConfig {
    #[serde(default)]
    temperature: Option<f32>,
}

#[derive(Debug, Clone, PartialEq, Default, Deserialize)]
struct GeminiContent {
    #[serde(default)]
    role: Option<String>,
    #[serde(default)]
    parts: Vec<GeminiPart>,
}

#[derive(Debug, Clone, PartialEq, Default, Deserialize)]
#[serde(rename_all = "camelCase")]
struct GeminiPart {
    #[serde(default)]
    text: Option<String>,
    #[serde(default)]
    function_call: Option<Value>,
    #[serde(default)]
    function_response: Option<Value>,
}

impl GeminiGenerateContentRequest {
    #[must_use]
    pub fn to_chat_completion_request(&self, model: &str) -> ChatCompletionRequest {
        let mut messages = Vec::new();
        if let Some(system) = self.system_instruction.as_ref() {
            let text = system.text();
            if !text.trim().is_empty() {
                messages.push(ChatMessage::new("system", text));
            }
        }

        let mut calls_by_name = HashMap::new();
        for (content_index, content) in self.contents.iter().enumerate() {
            let text = content.text();
            if !text.trim().is_empty() {
                messages.push(ChatMessage {
                    role: gemini_role_to_chat_role(content.role.as_deref()),
                    content: MessageContent::Text(text),
                    ..ChatMessage::default()
                });
            }
            let calls = content
                .parts
                .iter()
                .enumerate()
                .filter_map(|(part_index, part)| {
                    let call = part.function_call.as_ref()?;
                    let name = call.get("name")?.as_str()?.to_owned();
                    let arguments = call
                        .get("args")
                        .cloned()
                        .unwrap_or_else(|| json!({}))
                        .to_string();
                    let id = call.get("id").and_then(Value::as_str).map_or_else(
                        || {
                            crate::engine::stable_id(
                                "gemini_call",
                                &format!("{content_index}:{part_index}:{name}:{arguments}"),
                            )
                        },
                        str::to_owned,
                    );
                    calls_by_name.insert(name.clone(), id.clone());
                    Some(ToolCall::function(id, name, arguments))
                })
                .collect::<Vec<_>>();
            if !calls.is_empty() {
                messages.push(ChatMessage::assistant_tool_calls(calls));
            }
            for part in &content.parts {
                let Some(response) = part.function_response.as_ref() else {
                    continue;
                };
                let Some(name) = response.get("name").and_then(Value::as_str) else {
                    continue;
                };
                let id = response
                    .get("id")
                    .and_then(Value::as_str)
                    .map(str::to_owned)
                    .or_else(|| calls_by_name.get(name).cloned())
                    .unwrap_or_else(|| crate::engine::stable_id("gemini_call", name));
                let output = response.get("response").cloned().unwrap_or(Value::Null);
                messages.push(ChatMessage::tool_result(
                    id,
                    name.to_owned(),
                    match output {
                        Value::String(text) => text,
                        other => other.to_string(),
                    },
                ));
            }
        }

        ChatCompletionRequest {
            model: Some(resolve_model_id(Some(model))),
            messages,
            temperature: self
                .generation_config
                .as_ref()
                .and_then(|config| config.temperature),
            stream: false,
            tools: gemini_tools_to_openai(&self.tools),
            tool_choice: None,
            functions: Vec::new(),
            function_call: None,
            stream_options: None,
        }
    }
}

impl GeminiContent {
    fn text(&self) -> String {
        self.parts
            .iter()
            .filter_map(|part| part.text.as_deref())
            .filter(|text| !text.trim().is_empty())
            .collect::<Vec<_>>()
            .join("\n")
    }
}

fn gemini_role_to_chat_role(role: Option<&str>) -> String {
    match role {
        Some(role) if role.eq_ignore_ascii_case("model") => String::from("assistant"),
        Some(role) if role.eq_ignore_ascii_case("system") => String::from("system"),
        Some(role) if role.eq_ignore_ascii_case("assistant") => String::from("assistant"),
        _ => String::from("user"),
    }
}

fn gemini_tools_to_openai(tools: &[Value]) -> Vec<Value> {
    let mut definitions = Vec::new();
    for tool in tools {
        definitions.extend(
            tool.get("functionDeclarations")
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
                .filter_map(gemini_function_declaration_to_openai),
        );
        if tool.get("google_search").is_some() || tool.get("googleSearch").is_some() {
            definitions.push(hosted_gemini_tool("web_search"));
        }
        if tool.get("url_context").is_some() || tool.get("urlContext").is_some() {
            definitions.push(hosted_gemini_tool("web_fetch"));
        }
    }
    definitions
}

fn hosted_gemini_tool(name: &str) -> Value {
    json!({
        "type": "function",
        "function": {"name": name, "parameters": {"type": "object"}}
    })
}

fn gemini_function_declaration_to_openai(declaration: &Value) -> Option<Value> {
    let name = declaration.get("name")?.clone();
    let mut function = serde_json::Map::new();
    function.insert(String::from("name"), name);
    if let Some(description) = declaration.get("description") {
        function.insert(String::from("description"), description.clone());
    }
    if let Some(parameters) = declaration.get("parameters") {
        function.insert(String::from("parameters"), parameters.clone());
    }
    Some(json!({ "type": "function", "function": Value::Object(function) }))
}

