fn advertised_context_capacity() -> ContextCapacity {
    ContextCapacity::current()
        .unwrap_or_else(|_| ContextCapacity::from_bytes(0, 0, avg_utf8_bytes_per_char()))
}

fn gemini_response_from_chat_completion(completion: &ChatCompletion) -> Value {
    let choice = completion.choices.first();
    let parts = choice.map_or_else(Vec::new, |choice| {
        if choice.message.tool_calls.is_empty() {
            let text = choice.message.content.plain_text();
            if text.is_empty() {
                Vec::new()
            } else {
                vec![json!({ "text": text })]
            }
        } else {
            choice
                .message
                .tool_calls
                .iter()
                .map(|call| {
                    json!({
                        "functionCall": {
                            "id": call.id,
                            "name": call.function.name,
                            "args": serde_json::from_str::<Value>(&call.function.arguments)
                                .unwrap_or_else(|_| json!({}))
                        }
                    })
                })
                .collect()
        }
    });
    json!({
        "candidates": [{
            "content": {
                "role": "model",
                "parts": parts
            },
            "finishReason": "STOP",
            "index": 0
        }],
        "usageMetadata": {
            "promptTokenCount": completion.usage.prompt_tokens,
            "candidatesTokenCount": completion.usage.completion_tokens,
            "totalTokenCount": completion.usage.total_tokens
        },
        "modelVersion": completion.model
    })
}

