/// Build a Responses object from a deterministic [`AgenticPlan`] — the Responses
/// mirror of [`chat_completion_from_plan`]. A [`AgenticPlan::ToolCalls`] plan emits
/// `function_call` output items (the same stable `call` ids the chat surface uses);
/// a [`AgenticPlan::Final`] plan emits a single assistant message.
fn response_from_plan(
    request: &ResponsesRequest,
    prompt: &str,
    plan: AgenticPlan,
    memory_events: &[MemoryEvent],
) -> ResponseObject {
    let model = resolved_request_model(request.model.as_deref());
    let input_tokens = responses_input_tokens(request);

    let (output, output_tokens) = match plan {
        AgenticPlan::ToolCalls(calls) => {
            let mut items = Vec::with_capacity(calls.len());
            let mut output_tokens = 0u32;
            for (index, call) in calls.into_iter().enumerate() {
                let tool = call.tool;
                let planned_arguments = call.arguments;
                let seed = format!("{prompt}|{index}|{tool}|{planned_arguments}");
                let arguments =
                    response_arguments_for_tool(&request.tools, &tool, planned_arguments, prompt);
                output_tokens = output_tokens.saturating_add(
                    estimate_tokens(&tool).saturating_add(estimate_tokens(&arguments)),
                );
                if request
                    .tools
                    .iter()
                    .any(|definition| is_hosted_tool_definition(definition, &tool))
                    && tool == "web_search"
                {
                    let query = serde_json::from_str::<Value>(&arguments)
                        .ok()
                        .and_then(|value| {
                            value
                                .get("query")
                                .and_then(Value::as_str)
                                .map(str::to_owned)
                        })
                        .unwrap_or_else(|| prompt.to_owned());
                    items.push(ResponseOutputItem::WebSearchCall(
                        ResponseWebSearchToolCall {
                            id: stable_id("ws", &seed),
                            kind: String::from("web_search_call"),
                            status: String::from("completed"),
                            action: ResponseWebSearchAction {
                                kind: String::from("search"),
                                queries: vec![query.clone()],
                                query,
                            },
                        },
                    ));
                } else {
                    items.push(ResponseOutputItem::FunctionCall(ResponseFunctionToolCall {
                        id: stable_id("fc", &seed),
                        kind: function_call_kind(),
                        call_id: stable_id("call", &seed),
                        name: tool,
                        arguments,
                        status: String::from("completed"),
                    }));
                }
            }
            (items, output_tokens)
        }
        AgenticPlan::Final(answer) => {
            let answer = amended_answer(prompt, &answer, memory_events);
            let output_tokens = estimate_tokens(&answer);
            let message = ResponseOutputItem::Message(ResponseOutputMessage {
                id: stable_id("msg", &answer),
                kind: String::from("message"),
                role: String::from("assistant"),
                content: vec![ResponseOutputContent {
                    kind: String::from("output_text"),
                    text: answer,
    let chat_request = request.to_chat_completion_request();
    let completion = create_chat_completion_with_solver(&chat_request, solver);
    anthropic_message_from_chat_completion(request, &completion)
}

#[must_use]
pub fn create_anthropic_message_with_solver_and_memory(
    request: &AnthropicMessagesRequest,
    solver: &UniversalSolver,
    memory_events: &[MemoryEvent],
) -> AnthropicMessage {
    let chat_request = request.to_chat_completion_request();
    let completion =
        create_chat_completion_with_solver_and_memory(&chat_request, solver, memory_events);
    anthropic_message_from_chat_completion(request, &completion)
}

fn anthropic_message_from_chat_completion(
    request: &AnthropicMessagesRequest,
    completion: &ChatCompletion,
) -> AnthropicMessage {
    let model = crate::seed::resolve_model_id(request.model.as_deref());
    let choice = completion.choices.first();
    let requests_tools = choice.is_some_and(|choice| choice.finish_reason == "tool_calls");

    let (mut content, stop_reason, seed) = if requests_tools {
        let calls = choice
            .map(|choice| choice.message.tool_calls.clone())
            .unwrap_or_default();
        let seed = calls
            .iter()
            .map(|call| format!("{}({})", call.function.name, call.function.arguments))
            .collect::<Vec<_>>()
            .join("|");
        let blocks = calls.into_iter().map(tool_call_to_block).collect();
        (blocks, String::from("tool_use"), seed)
    } else {
        let text = choice
            .map(|choice| choice.message.content.plain_text())
            .unwrap_or_default();
        (
            vec![AnthropicContentBlock::text(text.clone())],
            String::from("end_turn"),
            text,
        )
    };

    // Extended thinking: when the client enabled it, lead the response with a
    // concrete `thinking` block built from the solver's naturalized reasoning
    // trace, mirroring the real Anthropic API (issue #488).
    if request.wants_thinking() {
        let steps = choice
            .map(|choice| choice.message.thinking_steps.as_slice())
            .unwrap_or_default();
        if let Some(block) = anthropic_thinking_block(steps) {
            content.insert(0, block);
        }
    }

    AnthropicMessage {
        id: stable_id("msg", &seed),
        kind: String::from("message"),
        role: String::from("assistant"),
        model,
        content,
        stop_reason,
        stop_sequence: None,
        usage: AnthropicUsage {
            input_tokens: completion.usage.prompt_tokens,
            output_tokens: completion.usage.completion_tokens,
        },
        context: json!(ContextCapacity::current()
            .unwrap_or_else(|_| { ContextCapacity::from_bytes(0, 0, avg_utf8_bytes_per_char()) })),
    }
}

/// Build the extended-thinking `thinking` content block from the solver's
/// concrete reasoning trace (issue #488). Each step is rendered by its
/// naturalized, human-readable `summary`; composite children are indented with a
/// `↳` marker so the recursively composite structure survives into the Anthropic
/// surface. The deterministic `signature` is a stable hash of the trace.
fn anthropic_thinking_block(steps: &[ThinkingStep]) -> Option<AnthropicContentBlock> {
    let text = render_thinking_steps(steps);
    if text.is_empty() {
        return None;
    }
    let signature = stable_id("thinking_signature", &text);
    Some(AnthropicContentBlock::thinking(text, signature))
}

