#[test]
fn compatibility_research_fetches_and_cites_independent_sources() {
    let mut messages = vec![ChatMessage::user(
        "Найди мне совместимую зарядку для Acer Aspire 3 A325-45?",
    )];
    let search = tool_calls(&messages);
