    );
    assert!(fetches.iter().all(|call| call.tool == "webfetch"));
    assert_eq!(
        fetches
            .iter()
            .map(|call| arguments(call)["url"].as_str().unwrap().to_owned())
            .collect::<Vec<_>>(),
        [
            "https://store.acer.com/a325-45",
