        );
        let next = dialog_id(
            &[],
            r#"{"messages":[{"role":"user","content":"Find a charger"},{"role":"assistant","content":"Searching"},{"role":"tool","content":"result"}]}"#,
            "/v1/chat/completions",
        );
        assert_eq!(first, next);
    }
}

