//! Capability-first routing for the shared agentic CLI tool set (issue #758).

use serde_json::json;

use super::general_planner::compose_edit_request;
use super::planner::{plan_one, AgenticPlan, Capability};
use crate::protocol::ChatMessage;
use crate::seed;

/// The first advertised tool name that provides `capability`, in canonical
/// alias order rather than the client's alphabetical tool order.
pub(super) fn tool_for<'a>(tool_names: &[&'a str], capability: Capability) -> Option<&'a str> {
    let registry = seed::agentic_tool_capabilities();
    let entry = registry
        .iter()
        .find(|entry| entry.id == capability.registry_id())?;
    entry.aliases.iter().find_map(|alias| {
        tool_names
            .iter()
            .copied()
            .find(|name| alias.eq_ignore_ascii_case(name))
    })
}

fn tool_matches_capability(name: &str, capability: Capability) -> bool {
    seed::agentic_tool_capabilities()
        .into_iter()
        .find(|entry| entry.id == capability.registry_id())
        .is_some_and(|entry| {
            entry
                .aliases
                .iter()
                .any(|alias| alias.eq_ignore_ascii_case(name))
        })
}

/// Classify a tool name through the shared alias registry, with legacy
/// substring matching as a compatibility fallback.
pub(super) fn classify_tool(name: &str) -> Option<Capability> {
    for capability in [
        Capability::Search,
        Capability::Fetch,
        Capability::Read,
        Capability::Write,
        Capability::Edit,
        Capability::Run,
        Capability::Grep,
        Capability::Glob,
        Capability::ListDir,
        Capability::Todo,
        Capability::Subagent,
        Capability::ReadMany,
        Capability::MultiEdit,
    ] {
        if tool_matches_capability(name, capability) {
            return Some(capability);
        }
    }
    let lower = name.to_ascii_lowercase();
    if lower.contains("todo") {
        return None;
    }
    if matches!(lower.as_str(), "computer_use" | "code_interpreter") {
        Some(Capability::Run)
    } else if lower.contains("search") {
        (lower.contains("web") && lower != "tool_search").then_some(Capability::Search)
    } else if lower == "read"
        || lower.contains("read_file")
        || lower.contains("read_local_file")
        || lower.contains("file_read")
        || lower.contains("open_file")
        || lower.contains("view_file")
    {
        Some(Capability::Read)
    } else if lower.contains("fetch")
        || lower.contains("open")
        || lower.contains("browse")
        || lower.contains("get_url")
        || lower.contains("read_url")
    {
        Some(Capability::Fetch)
    } else if lower.contains("write") || lower.contains("create_file") {
        Some(Capability::Write)
    } else if lower.contains("edit") || lower.contains("patch") || lower.contains("replace") {
        Some(Capability::Edit)
    } else if lower.contains("run")
        || lower.contains("bash")
        || lower.contains("command")
        || lower.contains("exec")
        || lower.contains("shell")
    {
        Some(Capability::Run)
    } else {
        None
    }
}

pub(super) fn plan_shared_capability_step(
    task: &str,
    messages: &[ChatMessage],
    tool_names: &[&str],
) -> Option<AgenticPlan> {
    let capability = [
        Capability::Grep,
        Capability::MultiEdit,
        Capability::ReadMany,
        Capability::Glob,
        Capability::ListDir,
        Capability::Todo,
        Capability::Subagent,
    ]
    .into_iter()
    .find(|capability| task_matches(task, *capability))?;
    if super::tool_result::has_latest_turn_result(messages) {
        return super::tool_result::latest_turn_answer(messages, tool_names, task)
            .map(AgenticPlan::Final);
    }
    if let Some(tool) = tool_for(tool_names, capability) {
        return Some(plan_one(tool, arguments_for(capability, task)));
    }
    if let Some(tool) = tool_for(tool_names, Capability::Run) {
        if let Some(command) = shell_fallback(capability, task) {
            return Some(plan_one(tool, json!({"command": command}).to_string()));
        }
    }
    None
}

fn task_matches(task: &str, capability: Capability) -> bool {
    let lower = task.to_lowercase();
    if capability == Capability::MultiEdit && file_tokens(task).len() > 1 {
        return compose_edit_request(task).is_some();
    }
    let id = capability.registry_id();
    seed::agentic_tool_capabilities()
        .into_iter()
        .find(|entry| entry.id == id)
        .is_some_and(|entry| entry.cues.iter().any(|cue| lower.contains(cue)))
}

fn arguments_for(capability: Capability, task: &str) -> String {
    match capability {
        Capability::Grep => {
            let query = super::shell_command::code_search_query_for_task(task)
                .unwrap_or_else(|| task.to_owned());
            json!({"query": query, "pattern": query}).to_string()
        }
        Capability::Glob => {
            let pattern = wildcard_token(task).unwrap_or("*");
            json!({"pattern": pattern, "path": "."}).to_string()
        }
        Capability::ListDir => json!({"path": "."}).to_string(),
        Capability::Todo => json!({
            "todos": [{"content": task, "status": "pending"}],
            "plan": [{"step": task, "status": "pending"}],
        })
        .to_string(),
        Capability::Subagent => json!({
            "description": task,
            "prompt": task,
            "input": task,
            "subagent_type": "general",
        })
        .to_string(),
        Capability::ReadMany => {
            let paths = file_tokens(task);
            json!({"paths": paths, "file_paths": paths}).to_string()
        }
        Capability::MultiEdit => {
            let (path, old, new) = compose_edit_request(task)
                .unwrap_or_else(|| (String::from("."), String::new(), String::new()));
            let paths = file_tokens(task);
            json!({
                "path": path,
                "paths": paths,
                "edits": [{
                    "old": old,
                    "new": new,
                    "old_string": old,
                    "new_string": new,
                }],
            })
            .to_string()
        }
        _ => json!({"prompt": task}).to_string(),
    }
}

fn wildcard_token(task: &str) -> Option<&str> {
    task.split_whitespace()
    plan_document_recipe(
        messages,
        tool_names,
        DocumentRecipe {
            path: google_trends_learning::GOOGLE_TRENDS_LEARNING_PATH,
            verify_command: google_trends_learning::verification_command(),
            final_answer,
            document,
        },
    )
}

fn plan_google_trends_catalog_step(messages: &[ChatMessage], tool_names: &[&str]) -> AgenticPlan {
    let document = google_trends_catalog::render_document();
    let final_answer = google_trends_catalog::final_answer(&document);
    plan_document_recipe(
        messages,
        tool_names,
        DocumentRecipe {
            path: google_trends_catalog::GOOGLE_TRENDS_CATALOG_PATH,
            verify_command: google_trends_catalog::verification_command(),
            final_answer,
            document,
        },
    )
}

pub(super) fn plan_one(tool: &str, arguments: String) -> AgenticPlan {
    AgenticPlan::ToolCalls(vec![PlannedToolCall {
        tool: tool.to_owned(),
        arguments,
    }])
}

/// Arguments for a write step that satisfy whichever key the advertised write
/// tool expects. Agentic CLIs disagree on the parameter name — the in-repo driver
/// reads `path`, the `@link-assistant/agent` CLI's `write` tool wants `filePath`,
/// others use `file_path`. All are emitted; a schema-validating CLI keeps the one
/// it declared and strips the rest, so the same plan drives any of them without a
/// per-CLI special case.
pub(super) fn write_arguments(path: &str, content: &str) -> String {
    json!({
        "path": path,
        "filePath": path,
        "file_path": path,
        "content": content,
    })
    .to_string()
}

/// Arguments for a fetch step. Emits `url` (the universal key) plus `format`
/// set to `"text"` — the `@link-assistant/agent` CLI's `webfetch` tool declares
/// a required `format` enum (`"text" | "markdown" | "html"`) and zod refuses the
/// call otherwise (observed live: *"Invalid option: expected one of
/// \"text\"|\"markdown\"|\"html\""*). The in-repo driver reads only `url`, and
/// CLIs whose schemas don't declare `format` strip it, so one shape drives all
/// of them without a per-CLI special case.
pub(super) fn fetch_arguments(url: &str) -> String {
    json!({
        "url": url,
        "format": "text",
    })
    .to_string()
}

pub(super) fn classify_tool(name: &str) -> Option<Capability> {
    capability_router::classify_tool(name)
}

/// The text of the most recent `user` turn.
fn latest_user_text(messages: &[ChatMessage]) -> Option<String> {
    messages
        .iter()
        .rev()
        .find(|message| message.role.eq_ignore_ascii_case("user"))
        .map(|message| message.content.user_request_text())
}

/// Keywords that mark a user turn as the canonical issue-#468 formalization task.
const FORMALIZATION_KEYWORDS: [&str; 7] = [
    "formaliz",
    "формализ",
    "knowledge base",
    "links notation",
    "рыбак",
    "fisherman",
    "сказк",
];

/// Whether `prompt` asks to formalize the canonical tale into a knowledge base.
fn is_formalization_task(prompt: &str) -> bool {
    let lower = prompt.to_lowercase();
    FORMALIZATION_KEYWORDS
        .iter()
        .any(|keyword| lower.contains(keyword))
}

/// The self-contained final answer: a natural-language summary, the coverage
/// line, and the Links Notation knowledge base inline.
fn final_answer(formalized: &FormalizedKnowledgeBase) -> String {
    let summary = &formalized.summary;
    let subject = if summary.doc_id == FISHERMAN_DOC_ID {
        "«Сказка о рыбаке и рыбке»".to_owned()
    } else {
        format!("the source text ({})", summary.doc_id)
    };
    format!(
        "Formalized {subject} into a Links Notation knowledge base: {records} records realising \
         all nine protocol primitives ({coverage}).\n\nKnowledge base ({KB_PATH}):\n\n{kb}",
        records = summary.total_records(),
        coverage = coverage_line(summary),
