    );
}

#[test]
fn anthropic_messages_explains_the_action_before_tool_use() {
    let request: AnthropicMessagesRequest = serde_json::from_value(serde_json::json!({
        "model": "formal-ai",
        "max_tokens": 1024,
        "messages": [{
            "role": "user",
            "content": "Find current evidence for this laptop charger?"
        }],
        "tools": [{
