pub(super) fn write_arguments(path: &str, content: &str) -> String {
    json!({
        "path": path,
        "filePath": path,
        "file_path": path,
        "content": content,
    })
    .to_string()
}

/// Arguments for a fetch step. Emits `url` (the universal key) plus `format`
/// set to `"text"` — the `@link-assistant/agent` CLI's `webfetch` tool declares
/// a required `format` enum (`"text" | "markdown" | "html"`) and zod refuses the
/// call otherwise (observed live: *"Invalid option: expected one of
/// \"text\"|\"markdown\"|\"html\""*). The in-repo driver reads only `url`, and
/// CLIs whose schemas don't declare `format` strip it, so one shape drives all
/// of them without a per-CLI special case.
pub(super) fn fetch_arguments(url: &str) -> String {
    json!({
        "url": url,
        "format": "text",
    })
    .to_string()
}

pub(super) fn classify_tool(name: &str) -> Option<Capability> {
    capability_router::classify_tool(name)
}

/// The text of the most recent `user` turn.
fn latest_user_text(messages: &[ChatMessage]) -> Option<String> {
    messages
        .iter()
        .rev()
        .find(|message| message.role.eq_ignore_ascii_case("user"))
        .map(|message| message.content.user_request_text())
}

/// Keywords that mark a user turn as the canonical issue-#468 formalization task.
const FORMALIZATION_KEYWORDS: [&str; 7] = [
    "formaliz",
    "формализ",
    "knowledge base",
    "links notation",
    "рыбак",
    "fisherman",
    "сказк",
];

/// Whether `prompt` asks to formalize the canonical tale into a knowledge base.
fn is_formalization_task(prompt: &str) -> bool {
    let lower = prompt.to_lowercase();
    FORMALIZATION_KEYWORDS
        .iter()
        .any(|keyword| lower.contains(keyword))
}

/// The self-contained final answer: a natural-language summary, the coverage
/// line, and the Links Notation knowledge base inline.
fn final_answer(formalized: &FormalizedKnowledgeBase) -> String {
    let summary = &formalized.summary;
    let subject = if summary.doc_id == FISHERMAN_DOC_ID {
        "«Сказка о рыбаке и рыбке»".to_owned()
    } else {
        format!("the source text ({})", summary.doc_id)
    };
    format!(
        "Formalized {subject} into a Links Notation knowledge base: {records} records realising \
         all nine protocol primitives ({coverage}).\n\nKnowledge base ({KB_PATH}):\n\n{kb}",
        records = summary.total_records(),
        coverage = coverage_line(summary),
        kb = formalized.links_notation.trim_end(),
    )
}
//! Capability-first routing for the shared agentic CLI tool set (issue #758).

use serde_json::json;

use super::general_planner::compose_edit_request;
use super::planner::{plan_one, AgenticPlan, Capability};
use crate::protocol::ChatMessage;
use crate::seed;

/// The advertised tool name that provides `capability`. Client-executed MCP
/// tools take precedence over protocol-native hosted tools: a hosted search is
/// executed by the upstream model provider, while an MCP tool produces a result
/// that the CLI can return in the next turn. Canonical aliases remain ordered by
/// the registry, followed by the compatibility classifier for namespaced tools
/// used by other harnesses.
pub(super) fn tool_for<'a>(tool_names: &[&'a str], capability: Capability) -> Option<&'a str> {
    if let Some(name) = tool_names.iter().copied().find(|name| {
        name.to_ascii_lowercase().starts_with("mcp__") && classify_tool(name) == Some(capability)
    }) {
        return Some(name);
    }
    let registry = seed::agentic_tool_capabilities();
    let entry = registry
        .iter()
        .find(|entry| entry.id == capability.registry_id())?;
    entry
        .aliases
        .iter()
        .find_map(|alias| {
            tool_names
                .iter()
                .copied()
                .find(|name| alias.eq_ignore_ascii_case(name))
        })
        .or_else(|| {
            tool_names
                .iter()
                .copied()
                .find(|name| classify_tool(name) == Some(capability))
        })
}

fn tool_matches_capability(name: &str, capability: Capability) -> bool {
    seed::agentic_tool_capabilities()
        .into_iter()
        .find(|entry| entry.id == capability.registry_id())
        .is_some_and(|entry| {
            entry
                .aliases
                .iter()
                .any(|alias| alias.eq_ignore_ascii_case(name))
        })
}

/// Classify a tool name through the shared alias registry, with legacy
/// substring matching as a compatibility fallback.
pub(super) fn classify_tool(name: &str) -> Option<Capability> {
    for capability in [
        Capability::Search,
        Capability::Fetch,
        Capability::Read,
        Capability::Write,
        Capability::Edit,
        Capability::Run,
        Capability::Grep,
        Capability::Glob,
        Capability::ListDir,
        Capability::Todo,
        Capability::Subagent,
        Capability::ReadMany,
        Capability::MultiEdit,
    ] {
        if tool_matches_capability(name, capability) {
            return Some(capability);
        }
    }
    let lower = name.to_ascii_lowercase();
    if lower.contains("todo") {
        return None;
    }
    if matches!(lower.as_str(), "computer_use" | "code_interpreter") {
        Some(Capability::Run)
    } else if lower.contains("search") {
        (lower.contains("web") && lower != "tool_search").then_some(Capability::Search)
    } else if lower == "read"
        || lower.contains("read_file")
        || lower.contains("read_local_file")
        || lower.contains("file_read")
        || lower.contains("open_file")
        || lower.contains("view_file")
    {
        Some(Capability::Read)
    } else if lower.contains("fetch")
        || lower.contains("open")
        || lower.contains("browse")
        || lower.contains("get_url")
        || lower.contains("read_url")
    {
        Some(Capability::Fetch)
    } else if lower.contains("write") || lower.contains("create_file") {
        Some(Capability::Write)
    } else if lower.contains("edit") || lower.contains("patch") || lower.contains("replace") {
        Some(Capability::Edit)
    } else if lower.contains("run")
        || lower.contains("bash")
        || lower.contains("command")
        || lower.contains("exec")
        || lower.contains("shell")
    {
        Some(Capability::Run)
#!/usr/bin/env node

// Deterministic, read-only web research fixture for issue #781 CLI E2E tests.
// Real Agent/OpenCode runs exercise their network-backed tools; Claude and Codex
// expose provider-hosted web search by default, so this MCP server gives those
// clients an executable tool whose result returns to the next model turn.

import readline from "node:readline";

const sources = new Map([
  [
    "https://acer.example.test/a325-45/specifications",
    "Acer Aspire 3 A325-45 specifications: the supplied adapter is rated 24 W.",
  ],
  [
    "https://parts.example.test/acer-a325-45/connector",
    "Acer Aspire 3 A325-45 power input: 12 V DC, 2 A, center-positive 3.5 x 1.35 mm barrel connector.",
  ],
  [
    "https://shop.example.test/compatible-a325-45-adapter",
    "Candidate adapter listing: 12 V, 2 A, 24 W, center-positive 3.5 x 1.35 mm plug; compatible with Acer Aspire 3 A325-45.",
  ],
]);

function result(id, value) {
  process.stdout.write(`${JSON.stringify({ jsonrpc: "2.0", id, result: value })}\n`);
}

function error(id, code, message) {
  process.stdout.write(
    `${JSON.stringify({ jsonrpc: "2.0", id, error: { code, message } })}\n`,
  );
}

function textResult(text) {
  return { content: [{ type: "text", text }], isError: false };
}

function handle(message) {
  const { id, method, params = {} } = message;
  if (method === "initialize") {
    result(id, {
      protocolVersion: params.protocolVersion || "2025-06-18",
      capabilities: { tools: {} },
      serverInfo: { name: "issue-781-research-fixture", version: "1.0.0" },
    });
    return;
  }
  if (method === "notifications/initialized" || method === "notifications/cancelled") {
    return;
  }
  if (method === "ping") {
    result(id, {});
    return;
  }
  if (method === "tools/list") {
    result(id, {
      tools: [
        {
          name: "websearch",
          description: "Search deterministic web evidence for the issue #781 charger task",
          inputSchema: {
            type: "object",
            properties: { query: { type: "string" } },
            required: ["query"],
            additionalProperties: false,
          },
          annotations: {
            title: "Search issue 781 fixture",
            readOnlyHint: true,
            destructiveHint: false,
            idempotentHint: true,
            openWorldHint: true,
          },
        },
        {
          name: "webfetch",
          description: "Fetch one deterministic issue #781 evidence page",
          inputSchema: {
            type: "object",
            properties: { url: { type: "string" } },
            required: ["url"],
            additionalProperties: false,
          },
          annotations: {
            title: "Fetch issue 781 fixture page",
            readOnlyHint: true,
            destructiveHint: false,
            idempotentHint: true,
            openWorldHint: true,
          },
        },
      ],
    });
    return;
  }
  if (method === "tools/call") {
    const name = params.name;
    const args = params.arguments || {};
    process.stderr.write(`[issue-781-mcp] ${name} ${JSON.stringify(args)}\n`);
    if (name === "websearch") {
      result(
        id,
        textResult(
          [
            "Acer specifications https://acer.example.test/a325-45/specifications",
            "Connector reference https://parts.example.test/acer-a325-45/connector",
            "Candidate listing https://shop.example.test/compatible-a325-45-adapter",
          ].join("\n"),
        ),
      );
      return;
    }
    if (name === "webfetch") {
      const body = sources.get(args.url);
      if (body) {
        result(id, textResult(body));
      } else {
        result(id, {
          content: [{ type: "text", text: `Error: fixture URL not found: ${args.url}` }],
          isError: true,
        });
      }
      return;
    }
    error(id, -32601, `Unknown tool: ${name}`);
    return;
  }
  if (id !== undefined) {
    error(id, -32601, `Unknown method: ${method}`);
  }
}

const input = readline.createInterface({ input: process.stdin, crlfDelay: Infinity });
input.on("line", (line) => {
  if (!line.trim()) return;
  try {
    handle(JSON.parse(line));
  } catch (exception) {
    process.stderr.write(`[issue-781-mcp] invalid request: ${exception.message}\n`);
  }
});

