      - name: Test release changelog collection
        run: rust-script --test scripts/version-and-commit.rs

      - name: Test fragment release map regeneration
        run: node --test experiments/issue_738_fragment_release_map.test.mjs

#!/usr/bin/env rust-script
//! Check for manual version modification in Cargo.toml
//!
//! This script prevents manual version changes in pull requests.
//! Versions should be managed automatically by the CI/CD pipeline
//! using changelog fragments in changelog.d/.
//!
//! Key behavior:
//! - Detects if `version = "..."` line has changed in Cargo.toml
//! - Fails the CI check if manual version change is detected
//! - Skips check for automated release branches (changelog-manual-release-*)
//!
//! Usage: rust-script scripts/check-version-modification.rs
//!
//! Environment variables (set by GitHub Actions):
//!   - GITHUB_HEAD_REF: The head branch name for PRs
//!   - GITHUB_BASE_REF: The base branch name for PRs
//!   - GITHUB_EVENT_NAME: Should be 'pull_request'
//!
//! Exit codes:
//!   - 0: No manual version changes detected (or check skipped)
//!   - 1: Manual version changes detected
//!
//! ```cargo
//! [dependencies]
//! regex = "1"
//! ```

use std::env;
use std::path::Path;
use std::process::{Command, exit};
use regex::Regex;

fn exec(command: &str, args: &[&str]) -> String {
    match Command::new(command).args(args).output() {
        Ok(output) => {
            String::from_utf8_lossy(&output.stdout).trim().to_string()
        }
        Err(_) => String::new(),
    }
}

fn exec_ignore_error(command: &str, args: &[&str]) {
    let _ = Command::new(command)
        .args(args)
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status();
}

fn should_skip_version_check() -> bool {
    let head_ref = env::var("GITHUB_HEAD_REF").unwrap_or_default();

    // Skip for automated release PRs
    let automated_branch_prefixes = [
        "changelog-manual-release-",
        "changeset-release/",
        "release/",
        "automated-release/",
    ];

    for prefix in &automated_branch_prefixes {
        if head_ref.starts_with(prefix) {
            println!("Skipping version check for automated branch: {}", head_ref);
            return true;
        }
    }

    false
}

fn get_rust_root() -> String {
    if let Ok(root) = env::var("RUST_ROOT") {
        if !root.is_empty() {
            return root;
        }
    }

    if Path::new("./Cargo.toml").exists() {
        return ".".to_string();
    }

    if Path::new("./rust/Cargo.toml").exists() {
        return "rust".to_string();
    }

    ".".to_string()
}

fn get_cargo_toml_path(rust_root: &str) -> String {
    if rust_root == "." {
        "Cargo.toml".to_string()
    } else {
        format!("{}/Cargo.toml", rust_root)
    }
}

fn get_cargo_toml_diff(cargo_toml_path: &str) -> String {
    let base_ref = env::var("GITHUB_BASE_REF").unwrap_or_else(|_| "main".to_string());

    // Ensure we have the base branch
    exec_ignore_error("git", &["fetch", "origin", &base_ref, "--depth=1"]);

    // Get the diff for Cargo.toml
    exec(
        "git",
        &["diff", &format!("origin/{}...HEAD", base_ref), "--", cargo_toml_path],
    )
}

fn has_version_change(diff: &str) -> bool {
    if diff.is_empty() {
        return false;
    }

    // Look for changes to the version line
    // Match lines that start with + or - followed by version = "..."
    let version_change_pattern = Regex::new(r#"(?m)^[+-]version\s*=\s*""#).unwrap();
    version_change_pattern.is_match(diff)
}

fn main() {
    println!("Checking for manual version modifications in Cargo.toml...\n");

    // Only run on pull requests
    let event_name = env::var("GITHUB_EVENT_NAME").unwrap_or_default();
    if event_name != "pull_request" {
        println!("Skipping: Not a pull request event (event: {})", event_name);
        exit(0);
    }

    // Skip for automated release branches
    if should_skip_version_check() {
        exit(0);
    }

    // Get and check the diff
    let rust_root = get_rust_root();
    let cargo_toml_path = get_cargo_toml_path(&rust_root);
    let diff = get_cargo_toml_diff(&cargo_toml_path);

    if diff.is_empty() {
        println!("No changes to Cargo.toml detected.");
        println!("Version check passed.");
        exit(0);
    }

    // Check for version changes
    if has_version_change(&diff) {
        eprintln!("Error: Manual version change detected in Cargo.toml!\n");
        eprintln!("Versions are managed automatically by the CI/CD pipeline.");
        eprintln!("Please do not modify the version field directly.\n");
        eprintln!("To trigger a release, add a changelog fragment to changelog.d/");
        eprintln!("with the appropriate bump type (major, minor, or patch).\n");
        eprintln!("See changelog.d/README.md for more information.\n");
        eprintln!("If you need to undo your version change, run:");
        eprintln!("  git checkout origin/main -- Cargo.toml");
        exit(1);
    }

    println!("Cargo.toml was modified but version field was not changed.");
    println!("Version check passed.");
}
# Issue 781 / pull 803 evidence bundle

This directory preserves the evidence used to reproduce, diagnose, fix, and
verify [formal-ai#781](https://github.com/link-assistant/formal-ai/issues/781)
in [PR #803](https://github.com/link-assistant/formal-ai/pull/803). Raw material
is retained alongside concise analysis so a reviewer can audit conclusions
without rerunning third-party clients or depending on mutable GitHub pages.

## Conclusions

- PR #795 implemented multi-source research, recursive follow-up, normalized
  shared-dialog ingestion, and a generic Links-based option network, but the
  July 19 reproduction showed its transport UX was still silent and could end
  without a usable response.
- The immediate stall was not one defect. Batched tool plans contained no
  user-facing narration; open-world requests could route to local grep;
  Responses namespace children were invisible to the planner or returned in an
  envelope Codex could not dispatch; and Codex transport wrappers polluted the
  URL/result data used by later turns.
- Formal AI now emits useful localized text before every research action, plans
  one search/fetch per turn, retains successful evidence by URL, and finishes
  with a cited synthesis. The same behavior is produced through Chat
  Completions, Responses, Anthropic Messages, and Gemini.
- Exact request/response bodies can now be recorded per dialog as JSONL by
  setting `FORMAL_AI_DIALOG_LOG_DIR`. Logging is off by default because bodies
  can contain private prompts and tool output.
- The reusable E2E drives the exact Russian prompt through Agent, OpenCode,
  Claude, and Codex. Each client performs one search, three separately narrated
  fetch turns, and a final synthesis. The deterministic MCP fixture isolates
  protocol behavior; separate native-network runs remain here as evidence of
  real provider and anti-bot variability.

## Analysis

- `analysis/timeline.md`: chronological reconstruction.
- `analysis/requirements.md`: exhaustive requirement-to-evidence trace.
- `analysis/root-causes.md`: each independently reproduced failure and its fix.
- `analysis/solution-plans.md`: alternatives, chosen design, remaining limits.
- `research/online-research.md`: official specifications, related components,
  known upstream defects, and source URLs.

## Raw evidence map

- `github/`: issue, comments, events, PR #795 and #803 records, diffs, screenshots,
  the 67,000-line reference AI session, and its compact event timeline.
- `ci-logs/`: historical branch run metadata and the complete 2,662-line log.
- `real-cli/`: native Agent/OpenCode/Claude/Codex experiments, including every
  failed intermediate Codex namespace/approval/normalization run.
- `real-cli/four-client-final-2/`: final four-client proof. Each client directory
  contains `client.log`, `formal-ai.log`, and `dialogs/*.jsonl`.
- `tests/`: focused red/green test logs and the final harness summary.
- `research/upstream/`: related Agent CLI and Codex issues plus the exact public
  Codex report submitted during this investigation.
- top-level `reproduction-*-before-fix.log` / `*-after-fix.log`: minimum
  reproductions for narration, action sequencing, intent routing, namespace
  visibility, namespace dispatch, and transport-envelope normalization.

## Fastest audit path

1. Read `github/issue-view.txt` and the two validated PNG screenshots.
2. Compare `reproduction-before-fix.log` with `reproduction-after-core-fix.log`.
3. Read `tests/four-client-harness-final-2.log`.
4. Inspect one final dialog file, for example
