    }

    #[test]
    fn expanded_histories_share_the_first_user_prompt_id() {
        let first = dialog_id(
            &[],
            r#"{"messages":[{"role":"user","content":"Find a charger"}]}"#,
            "/v1/chat/completions",
        );
        let next = dialog_id(
            &[],
            r#"{"messages":[{"role":"user","content":"Find a charger"},{"role":"assistant","content":"Searching"},{"role":"tool","content":"result"}]}"#,
            "/v1/chat/completions",
