}
//! Reading a turn's tool results back out of the transcript (issue #468).
//!
//! The planner is stateless: it re-derives what to do next from the conversation
//! alone, so "what has already been tried this turn" has to be *read* rather than
//! remembered. That reading is this module, and it is a separate concern from
//! choosing the next step — [`Progress::scan`] answers what happened, and
//! `planner` decides what happens next.

use super::planner::{classify_tool, Capability};
use crate::protocol::ChatMessage;

/// Tool results produced since the current user turn began.
pub struct Progress {
    completed: Vec<Capability>,
    pub(super) fetched_text: Option<String>,
    pub(super) fetched_pages: Vec<(String, String)>,
    pub(super) attempted_fetches: Vec<String>,
    pub(super) search_output: Option<String>,
    pub(super) run_output: Option<String>,
    pub(super) fetch_result: Option<String>,
    pub(super) search_result: Option<String>,
}

impl Progress {
    pub(super) fn scan(messages: &[ChatMessage]) -> Self {
        let mut completed = Vec::new();
        let mut fetched_text = None;
        let mut fetched_pages = Vec::new();
        let mut attempted_fetches = Vec::new();
        let mut search_output = None;
        let mut run_output = None;
        let mut fetch_result = None;
        let mut search_result = None;
        // Ignore results from earlier user turns.
        let current_turn = messages
            .iter()
            .rposition(|message| message.role.eq_ignore_ascii_case("user"))
            .map_or(0, |index| index + 1);
        for (index, message) in messages.iter().enumerate().skip(current_turn) {
            if !message.role.eq_ignore_ascii_case("tool") {
                continue;
            }
            let Some(capability) = result_capability(messages, index) else {
                continue;
            };
            if capability == Capability::Fetch {
                let payload = super::tool_result::normalized_payload(&message.content.plain_text());
                fetch_result = Some(payload.clone().unwrap_or_default());
                let fetch_url = result_tool_cal…57 tokens truncated…               }
                }
                if let Some(text) = payload.filter(|text| !text.trim().is_empty()) {
                    if let Some(url) = fetch_url {
                        fetched_pages.push((url, text.clone()));
                    }
                    fetched_text = Some(text);
                }
            }
            if capability == Capability::Search {
                let payload = super::tool_result::normalized_payload(&message.content.plain_text());
                search_result = Some(payload.clone().unwrap_or_default());
                if let Some(text) = payload.filter(|text| !text.trim().is_empty()) {
                    search_output = Some(text);
                }
            }
            if capability == Capability::Run {
                run_output = Some(message.content.plain_text());
            }
            completed.push(capability);
        }
        Self {
            completed,
            fetched_text,
            fetched_pages,
            attempted_fetches,
            search_output,
            run_output,
            fetch_result,
            search_result,
        }
    }

    /// Whether a prior tool result already covered `capability`.
    pub(super) fn done(&self, capability: Capability) -> bool {
        self.completed.contains(&capability)
    }

    pub(super) fn count(&self, capability: Capability) -> usize {
        self.completed
            .iter()
            .filter(|done| **done == capability)
            .count()
    }

    /// The capability of the most recent tool result in this turn.
    ///
    /// `completed` is in arrival order, so this distinguishes *which phase* a
    /// multi-round loop is in — a search that has not been read yet, versus a
    /// completed read — which [`Progress::done`] alone cannot, since it stays
    /// true for every later round.
    pub(super) fn last(&self) -> Option<Capability> {
        self.completed.last().copied()
    }

    pub(super) fn fetch_result(&self) -> Option<&str> {
        self.fetch_result.as_deref()
    }

    pub(super) fn search_result(&self) -> Option<&str> {
        self.search_result.as_deref()
    }
}

/// Resolve which capability the tool result at `index` answers. Prefer the
/// result's own `name`; otherwise map its `tool_call_id` back to the tool name in
/// a prior assistant `tool_calls` turn.
fn result_capability(messages: &[ChatMessage], index: usize) -> Option<Capability> {
    let message = &messages[index];
    if let Some(name) = &message.name {
        if let Some(capability) = classify_tool(name) {
            return Some(capability);
        }
    }
    result_tool_call(messages, index).and_then(|call| classify_tool(&call.function.name))
}

fn result_tool_call(messages: &[ChatMessage], index: usize) -> Option<&crate::protocol::ToolCall> {
    let call_id = messages[index].tool_call_id.as_ref()?;
    messages[..index]
        .iter()
        .rev()
        .flat_map(|prior| prior.tool_calls.iter())
        .find(|call| &call.id == call_id)
}

fn fetch_call_url(call: &crate::protocol::ToolCall) -> Option<String> {
    let arguments: serde_json::Value = serde_json::from_str(&call.function.arguments).ok()?;
    arguments
        .get("url")
        .and_then(serde_json::Value::as_str)
        .filter(|url| !url.trim().is_empty())
        .map(str::to_owned)
}
//! Friendly, lossless presentation of client-owned tool results (issue #750).

use serde_json::Value;

use crate::protocol::ChatMessage;
use crate::seed::{
    ROLE_TOOL_RESULT_DETAIL_REQUEST, ROLE_TOOL_RESULT_FIRST_REFERENCE,
    ROLE_TOOL_RESULT_LINE_REQUEST, ROLE_TOOL_RESULT_SECOND_REFERENCE, ROLE_TOOL_RESULT_URL_REQUEST,
};

struct NormalizedResult {
    payload: String,
    error: Option<String>,
    format: &'static str,
}

/// Remove client transport wrappers while preserving the tool's actual text.
/// Agentic planners consume this form; durable protocol recording still keeps
/// the original result byte-for-byte.
pub(super) fn normalized_payload(raw: &str) -> Option<String> {
    let result = normalize(raw);
    (result.error.is_none() && !looks_like_error(&result.payload)).then_some(result.payload)
}

fn looks_like_error(text: &str) -> bool {
    let lower = text.to_lowercase();
    ["error", "failed", "not found", "404"]
        .iter()
        .any(|needle| lower.contains(needle))
}

pub(super) fn render(label: &str, raw: &str, prompt: &str) -> String {
    let result = normalize(raw);
    let language = response_language(prompt);
    if let Some(error) = result.error {
        return fill("tool_result_failed", language, label, "", "", &error);
    }
    if result.payload.trim().is_empty() {
        let intent = if is_listing(label) {
            "tool_result_empty_list"
        } else if is_search(label) {
            "tool_result_empty_search"
        } else {
            "tool_result_empty_generic"
        };
        return fill(intent, language, label, "", "", "");
    }
    fill(
        "tool_result_completed",
        language,
        label,
        result.format,
        &result.payload,
        "",
    )
}

pub(super) fn latest_turn_answer(
    messages: &[ChatMessage],
    tool_names: &[&str],
    prompt: &str,
) -> Option<String> {
    let start = messages
        .iter()
        .rposition(|message| message.role.eq_ignore_ascii_case("user"))?;
    let (index, result) = messages
        .iter()
        .enumerate()
        .skip(start + 1)
        .rev()
        .find(|(_, message)| message.role.eq_ignore_ascii_case("tool"))?;
    if is_write_run_recipe(messages, tool_names) {
        return None;
    }
    let label = result_label(messages, index);
    Some(render(&label, &result.content.plain_text(), prompt))
}

pub(super) fn has_latest_turn_result(messages: &[ChatMessage]) -> bool {
    let Some(start) = messages
        .iter()
        .rposition(|message| message.role.eq_ignore_ascii_case("user"))
    else {
        return false;
    };
    messages
        .iter()
        .skip(start + 1)
        .any(|message| message.role.eq_ignore_ascii_case("tool"))
}

fn is_write_run_recipe(messages: &[ChatMessage], tool_names: &[&str]) -> bool {
    let is_write = |name: &str| {
        let lower = name.to_ascii_lowercase();
        lower.contains("write") || lower.contains("create_file")
    };
    let is_run = |name: &str| {
        let lower = name.to_ascii_lowercase();
        lower.contains("run")
            || lower.contains("bash")
            || lower.contains("command")
            || lower.contains("exec")
            || lower.contains("shell")
    };
    tool_names.iter().copied().any(is_write)
        && tool_names.iter().copied().any(is_run)
        && messages
            .iter()
            .flat_map(|message| &message.tool_calls)
            .any(|call| is_write(&call.function.name))
}

pub(super) fn follow_up_answer(messages: &[ChatMessage], prompt: &str) -> Option<String> {
    let normalized_prompt = crate::engine::normalize_prompt(prompt);
    let lexicon = crate::seed::lexicon();
    let wants_url = lexicon.mentions_role(ROLE_TOOL_RESULT_URL_REQUEST, &normalized_prompt);
    let wants_line = lexicon.mentions_role(ROLE_TOOL_RESULT_LINE_REQUEST, &normalized_prompt);
    let wants_detail = lexicon.mentions_role(ROLE_TOOL_RESULT_DETAIL_REQUEST, &normalized_prompt);
    if !wants_url && !wants_line && !wants_detail {
        return None;
    }
    let latest_user = messages
        .iter()
        .rposition(|message| message.role.eq_ignore_ascii_case("user"))?;
    let result = messages[..latest_user]
        .iter()
        .rev()
        .find(|message| message.role.eq_ignore_ascii_case("tool"))?;
    let result = normalize(&result.content.plain_text());
    if wants_url {
        let urls = extract_urls(&result.payload);
        return urls
            .get(requested_index(lexicon, &normalized_prompt))
            .cloned();
    }
    if wants_line {
        return result
            .payload
            .lines()
            .nth(requested_index(lexicon, &normalized_prompt))
            .map(str::to_owned);
    }
    Some(result.payload)
}

fn requested_index(lexicon: &crate::seed::Lexicon, prompt: &str) -> usize {
    if lexicon.mentions_role(ROLE_TOOL_RESULT_SECOND_REFERENCE, prompt) {
        return 1;
    }
    if lexicon.mentions_role(ROLE_TOOL_RESULT_FIRST_REFERENCE, prompt) {
        return 0;
    }
    prompt
        .split(|character: char| !character.is_ascii_digit())
        .find_map(|digits| digits.parse::<usize>().ok())
        .unwrap_or(1)
        .saturating_sub(1)
}

fn normalize(raw: &str) -> NormalizedResult {
    let trimmed = raw.trim();
    let Ok(value) = serde_json::from_str::<Value>(trimmed) else {
        return from_payload(&strip_transport_envelope(trimmed), None);
    };
    let Some(object) = value.as_object() else {
        return from_payload(&pretty_json(&value), None);
    };
    let nonzero_exit = ["exit_code", "exitCode"]
        .iter()
        .filter_map(|key| object.get(*key))
        .any(nonzero_status);
    let failed_http = object
        .get("status_code")
        .and_then(Value::as_u64)
        .is_some_and(|status| status >= 400);
    let failed_status = object.get("status").is_some_and(failed_status);
    let explicitly_unsuccessful = object.get("success").and_then(Value::as_bool) == Some(false);
    let explicit_error = ["error", "stderr", "failure"]
        .iter()
        .filter_map(|key| object.get(*key))
        .find_map(nonempty_text);
    if nonzero_exit
        || failed_http
        || failed_status
        || explicitly_unsuccessful
        || explicit_error.is_some()
    {
        let error = explicit_error
            .or_else(|| object.get("output").and_then(nonempty_text))
            .or_else(|| {
                ["exit_code", "exitCode", "status_code", "status"]
                    .iter()
                    .find_map(|key| object.get(*key).map(|value| format!("{key}={value}")))
            })
            .unwrap_or_default();
        return from_payload("", Some(error));
    }
    if let Some(payload) = ["output", "stdout", "content", "result"]
        .iter()
        .find_map(|key| object.get(*key))
    {
        let payload = payload
            .as_str()
            .map_or_else(|| pretty_json(payload), strip_transport_envelope);
        return from_payload(&payload, None);
    }
    from_payload(&pretty_json(&value), None)
}

fn from_payload(payload: &str, error: Option<String>) -> NormalizedResult {
    let trimmed = payload.trim().to_owned();
    if let Ok(json) = serde_json::from_str::<Value>(&trimmed) {
        if let Some(text) = mcp_text_content(&json) {
            return NormalizedResult {
                payload: text,
                error,
                format: "text",
            };
        }
        return NormalizedResult {
            payload: pretty_json(&json),
            error,
            format: "json",
        };
    }
    let format = if trimmed.starts_with("#!/bin/bash") || trimmed.starts_with("#!/usr/bin/env bash")
    {
        "bash"
    } else if trimmed.starts_with("#!/usr/bin/env python") {
        "python"
    } else {
        "text"
    };
    NormalizedResult {
        payload: trimmed,
        error,
        format,
    }
}

fn mcp_text_content(value: &Value) -> Option<String> {
    let content = value
        .as_object()
        .and_then(|object| object.get("content"))
        .unwrap_or(value)
        .as_array()?;
    if content.is_empty() {
        return None;
    }
    let text = content
        .iter()
        .map(|item| {
            let object = item.as_object()?;
            (object.get("type").and_then(Value::as_str) == Some("text"))
                .then(|| object.get("text").and_then(Value::as_str))
                .flatten()
        })
        .collect::<Option<Vec<_>>>()?;
    Some(text.join("\n"))
}
//! Issue #687 — driving Formal AI as an agentic backend (`OpenCode`) must actually
//! *act* on simple natural-language requests instead of falling to the
//! unknown-reasoning blurb.
//!
//! The four prompts from the reported `OpenCode` session each name a capability the
//! agentic planner should exercise through the client's advertised tools:
//!
//! 1. a factual question → a real web search tool call (the harness runs it);
//! 2. "report [this] on GitHub" → a `gh issue create` shell tool call against the
//!    Formal AI repository;
//! 3. "what were we talking about?" → a conversational-recall final answer built
//!    from the message history;
//! 4. "learn about it." → resolve the pronoun from history and research the topic.
//!
//! These assert the *agentic* path (`plan_chat_step`), which is exactly how an
//! external agentic CLI such as `OpenCode` drives the OpenAI-compatible server.

use formal_ai::agentic_coding::{plan_chat_step, AgenticPlan, PlannedToolCall};
use formal_ai::protocol::ChatMessage;

/// The tools a typical agentic CLI (`OpenCode`) advertises.
const TOOLS: [&str; 5] = ["websearch", "webfetch", "read", "write", "bash"];

fn plan(messages: &[ChatMessage]) -> AgenticPlan {
    plan_chat_step(messages, &TOOLS).expect("planner should recognise the task")
}

fn tool_calls(messages: &[ChatMessage]) -> Vec<PlannedToolCall> {
    match plan(messages) {
        AgenticPlan::ToolCalls(calls) => calls,
        plan @ AgenticPlan::Final(_) => panic!("expected tool calls, got {plan:?}"),
    }
}

fn final_answer(messages: &[ChatMessage]) -> String {
    match plan(messages) {
        AgenticPlan::Final(answer) => answer,
        plan @ AgenticPlan::ToolCalls(_) => panic!("expected final answer, got {plan:?}"),
    }
}

fn arguments(call: &PlannedToolCall) -> serde_json::Value {
    serde_json::from_str(&call.arguments).expect("tool arguments should be JSON")
}

// Requirement 1: factual questions go to the web instead of the unknown blurb.
mod factual_question {
    use super::*;

    #[test]
    fn future_election_question_emits_a_web_search() {
        for prompt in [
            "When are the next elections in the USA?",
            "When next elections in the USA?",
            "What is the current population of Japan?",
        ] {
            let messages = vec![ChatMessage::user(prompt)];
            let calls = tool_calls(&messages);
            assert_eq!(calls.len(), 1, "{prompt:?} should emit one call");
            assert_eq!(calls[0].tool, "websearch", "{prompt:?} should web-search");
            let query = arguments(&calls[0])["query"]
                .as_str()
                .expect("query string")
                .to_lowercase();
            assert!(!query.is_empty(), "{prompt:?} query must not be empty");
        }
    }

    #[test]
    fn election_search_then_fetch_then_answers_from_results() {
        let mut messages = vec![ChatMessage::user("When are the next elections in the USA?")];

        let search = tool_calls(&messages).remove(0);
        assert_eq!(search.tool, "websearch");
        answer_tool_call(
            &mut messages,
            &search,
            "US general elections are scheduled for November 3, 2026. \
             Source: https://www.usa.gov/election-day",
        );

        // With a fetch tool advertised and a URL in the search result, the planner
        // fetches the source before answering.
        let fetch = tool_calls(&messages).remove(0);
        assert_eq!(fetch.tool, "webfetch");
        assert_eq!(
            arguments(&fetch)["url"],
            "https://www.usa.gov/election-day",
            "planner should fetch the URL surfaced by the search"
        );
        answer_tool_call(
            &mut messages,
            &fetch,
            "The next U.S. general election is on Tuesday, November 3, 2026.",
        );

        let answer = final_answer(&messages);
        assert!(
            answer.contains("2026"),
            "final answer must carry the fetched fact, got: {answer}"
        );
    }

    #[test]
    fn research_prefers_an_official_source_and_cites_it() {
        let mut messages = vec![ChatMessage::user("When are the next elections in the USA?")];
        let search = tool_calls(&messages).remove(0);
        answer_tool_call(
            &mut messages,
            &search,
            "Commentary https://example.com/elections Official https://www.usa.gov/election-day",
        );

        let fetch = tool_calls(&messages).remove(0);
        assert_eq!(fetch.tool, "webfetch");
        assert_eq!(arguments(&fetch)["url"], "https://www.usa.gov/election-day");
        answer_tool_call(&mut messages, &fetch, "Election Day is November 3, 2026.");

        let answer = final_answer(&messages);
        assert!(answer.contains("November 3, 2026"), "{answer}");
        assert!(
            answer.contains("https://www.usa.gov/election-day"),
            "{answer}"
        );
    }
